<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Conway's Game of Life</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b16;
      --panel: #14182a;
      --text: #f4f5ff;
      --muted: #9ca5c7;
      --accent: #70f0c0;
      --accent2: #9b7cff;
    }

    * { box-sizing: border-box; }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      overflow-x: hidden;
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 20% 15%, #292055 0, transparent 32rem),
        radial-gradient(circle at 80% 85%, #123d42 0, transparent 28rem),
        var(--bg);
    }

    main {
      width: min(94vw, 720px);
      padding: 28px 16px;
      text-align: center;
    }

    h1 {
      margin: 0 0 6px;
      font-size: clamp(2rem, 6vw, 3.5rem);
      line-height: 1;
      letter-spacing: -0.06em;
    }

    .subtitle {
      margin: 0 0 20px;
      color: var(--muted);
    }

    .stage {
      display: inline-block;
      padding: 10px;
      border: 1px solid #ffffff22;
      border-radius: 20px;
      background: #080a12cc;
      box-shadow: 0 22px 70px #0009, inset 0 1px #ffffff12;
    }

    #life {
      display: block;
      width: min(82vw, 600px);
      height: min(82vw, 600px);
      min-width: 400px;
      min-height: 400px;
      border-radius: 12px;
      background: #080a12;
      cursor: crosshair;
      touch-action: none;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
      margin-top: 18px;
    }

    button {
      min-width: 105px;
      padding: 11px 17px;
      border: 1px solid #ffffff20;
      border-radius: 999px;
      color: var(--text);
      background: linear-gradient(180deg, #252b46, #181c31);
      box-shadow: 0 6px 16px #0005, inset 0 1px #ffffff18;
      font: 700 0.95rem inherit;
      cursor: pointer;
      transition: transform 120ms ease, border-color 120ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      border-color: #70f0c088;
    }

    button:active { transform: translateY(1px) scale(0.98); }

    #play {
      color: #08120f;
      border-color: transparent;
      background: linear-gradient(135deg, var(--accent), #65bdff);
    }

    #play.running {
      background: linear-gradient(135deg, #ffcf66, #ff7c9d);
    }

    .status {
      margin-top: 13px;
      color: var(--muted);
      font-size: 0.9rem;
    }

    #generation {
      color: var(--accent);
      font-weight: 800;
    }

    @media (max-width: 450px) {
      main { width: 100%; padding-inline: 4px; }
      .stage { padding: 6px; }
      #life {
        width: 400px;
        height: 400px;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Life, uh… finds a way.</h1>
    <p class="subtitle">Draw tiny civilizations, then watch the drama unfold.</p>

    <div class="stage">
      <canvas id="life" width="600" height="600" aria-label="Conway's Game of Life grid"></canvas>
    </div>

    <div class="controls">
      <button id="step" type="button">Step ✦</button>
      <button id="play" type="button">Play ▶</button>
      <button id="random" type="button">Random ✨</button>
      <button id="clear" type="button">Clear ☁</button>
    </div>

    <div class="status">Generation <span id="generation">0</span> · drag to paint</div>
  </main>

  <script>
    (() => {
      "use strict";

      const w = 60;
      const h = 60;
      const canvas = document.getElementById("life");
      const ctx = canvas.getContext("2d");
      const generationNode = document.getElementById("generation");
      const playButton = document.getElementById("play");

      let cells = new Uint8Array(w * h);
      let generation = 0;
      let timer = null;
      let drawing = false;
      let paintValue = 1;
      let lastPainted = -1;

      function index(x, y) {
        return y * w + x;
      }

      function get(x, y) {
        if (x < 0 || y < 0 || x >= w || y >= h) return 0;
        return cells[index(x, y)];
      }

      function resizeCanvas() {
        const rect = canvas.getBoundingClientRect();
        const dpr = Math.max(1, window.devicePixelRatio || 1);
        const pixelWidth = Math.round(rect.width * dpr);
        const pixelHeight = Math.round(rect.height * dpr);

        if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
          canvas.width = pixelWidth;
          canvas.height = pixelHeight;
        }

        draw();
      }

      function draw() {
        const cw = canvas.width / w;
        const ch = canvas.height / h;

        ctx.fillStyle = "#080a12";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.strokeStyle = "#7480a315";
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let x = 1; x < w; x++) {
          const px = Math.round(x * cw) + 0.5;
          ctx.moveTo(px, 0);
          ctx.lineTo(px, canvas.height);
        }
        for (let y = 1; y < h; y++) {
          const py = Math.round(y * ch) + 0.5;
          ctx.moveTo(0, py);
          ctx.lineTo(canvas.width, py);
        }
        ctx.stroke();

        ctx.fillStyle = "#70f0c0";
        ctx.shadowColor = "#70f0c0";
        ctx.shadowBlur = Math.max(2, cw * 0.28);

        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            if (cells[index(x, y)]) {
              const inset = Math.max(1, cw * 0.1);
              ctx.fillRect(
                x * cw + inset,
                y * ch + inset,
                Math.max(1, cw - inset * 2),
                Math.max(1, ch - inset * 2)
              );
            }
          }
        }

        ctx.shadowBlur = 0;
        generationNode.textContent = String(generation);
      }

      function set(x, y, value) {
        x = Math.trunc(x);
        y = Math.trunc(y);
        if (x < 0 || y < 0 || x >= w || y >= h) return;
        cells[index(x, y)] = value ? 1 : 0;
        draw();
      }

      function step() {
        const next = new Uint8Array(w * h);

        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            let neighbours = 0;

            for (let dy = -1; dy <= 1; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                if (dx !== 0 || dy !== 0) {
                  neighbours += get(x + dx, y + dy);
                }
              }
            }

            const alive = cells[index(x, y)] === 1;
            next[index(x, y)] =
              neighbours === 3 || (alive && neighbours === 2) ? 1 : 0;
          }
        }

        cells = next;
        generation++;
        draw();
      }

      function clear() {
        cells.fill(0);
        generation = 0;
        draw();
      }

      function randomize() {
        generation = 0;
        for (let i = 0; i < cells.length; i++) {
          cells[i] = Math.random() < 0.28 ? 1 : 0;
        }
        draw();
      }

      function stop() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
        playButton.textContent = "Play ▶";
        playButton.classList.remove("running");
      }

      function togglePlay() {
        if (timer !== null) {
          stop();
        } else {
          timer = setInterval(step, 110);
          playButton.textContent = "Pause ❚❚";
          playButton.classList.add("running");
        }
      }

      function eventCell(event) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((event.clientX - rect.left) * w / rect.width);
        const y = Math.floor((event.clientY - rect.top) * h / rect.height);
        return { x, y };
      }

      function paint(event, first) {
        const { x, y } = eventCell(event);
        if (x < 0 || y < 0 || x >= w || y >= h) return;

        const i = index(x, y);
        if (first) paintValue = cells[i] ? 0 : 1;
        if (i === lastPainted) return;

        cells[i] = paintValue;
        lastPainted = i;
        draw();
      }

      canvas.addEventListener("pointerdown", event => {
        event.preventDefault();
        stop();
        drawing = true;
        lastPainted = -1;
        canvas.setPointerCapture(event.pointerId);
        paint(event, true);
      });

      canvas.addEventListener("pointermove", event => {
        if (drawing) paint(event, false);
      });

      canvas.addEventListener("pointerup", event => {
        drawing = false;
        lastPainted = -1;
        if (canvas.hasPointerCapture(event.pointerId)) {
          canvas.releasePointerCapture(event.pointerId);
        }
      });

      canvas.addEventListener("pointercancel", () => {
        drawing = false;
        lastPainted = -1;
      });

      document.getElementById("step").addEventListener("click", () => {
        stop();
        step();
      });
      playButton.addEventListener("click", togglePlay);
      document.getElementById("random").addEventListener("click", randomize);
      document.getElementById("clear").addEventListener("click", () => {
        stop();
        clear();
      });

      window.life = { w, h, get, set, step, clear };

      window.addEventListener("resize", resizeCanvas);
      resizeCanvas();
    })();
  </script>
</body>
</html>
